import{_ as o,C as r,o as n,c as d,j as t,a as s,E as c,al as i}from"./chunks/framework.7vp1BMOE.js";const m=JSON.parse('{"title":"u-blox Diagnostics with u-center","description":"","frontmatter":{},"headers":[],"relativePath":"uk/gps_compass/u-center.md","filePath":"uk/gps_compass/u-center.md"}'),h={name:"uk/gps_compass/u-center.md"};function l(u,e,p,f,b,g){const a=r("Badge");return n(),d("div",null,[e[0]||(e[0]=t("h1",{id:"u-blox-diagnostics-with-u-center",tabindex:"-1"},[s("u-blox Diagnostics with u-center "),t("a",{class:"header-anchor",href:"#u-blox-diagnostics-with-u-center","aria-label":'Permalink to "u-blox Diagnostics with u-center"'},"​")],-1)),c(a,{type:"tip",text:"main (PX4 v2.0)"}),e[1]||(e[1]=i('<p><a href="https://www.u-blox.com/en/product/u-center" target="_blank" rel="noreferrer">u-center</a> is u-blox&#39;s desktop tool for monitoring a receiver&#39;s live satellite, signal, and position data, and for reading and writing its configuration.</p><p>Setting <a href="#GPS_UBX_MODE">GPS_UBX_MODE</a> to <code>7</code> configures a u-blox receiver&#39;s <code>UART2</code> as a UBX diagnostic port for <a href="https://www.u-blox.com/en/product/u-center" target="_blank" rel="noreferrer">u-center</a>, while the receiver continues to serve the autopilot on <code>UART1</code> (as usual). This is useful for diagnosing poor fixes, interference, or RTK issues without disconnecting the autopilot.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Heading and static-base-on-UART2 setups cannot use this feature. For more information see <a href="#constraints">Constraints</a> below.</p></div><h2 id="підключення" tabindex="-1">Підключення <a class="header-anchor" href="#підключення" aria-label="Permalink to &quot;Підключення&quot;">​</a></h2><p>Connect the adapter&#39;s RX to the receiver&#39;s <code>UART2</code> TX, its TX to <code>UART2</code> RX, and share ground. u-blox UART pins are 3.3 V.</p><h2 id="конфігурація-px4" tabindex="-1">Конфігурація PX4 <a class="header-anchor" href="#конфігурація-px4" aria-label="Permalink to &quot;Конфігурація PX4&quot;">​</a></h2><p>The parameters to set:</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Налаштування</th></tr></thead><tbody><tr><td><a id="GPS_UBX_MODE"></a><a href="./../advanced_config/parameter_reference#GPS_UBX_MODE">GPS_UBX_MODE</a></td><td><code>u-center on UART2</code> (7)</td></tr><tr><td><a href="./../advanced_config/parameter_reference#GPS_UBX_BAUD2">GPS_UBX_BAUD2</a></td><td>UART2 baudrate, must match the USB-serial adapter (default 230400)</td></tr></tbody></table><p>Both parameters take effect after a reboot.</p><h2 id="messages-enabled-on-uart2" tabindex="-1">Messages Enabled on UART2 <a class="header-anchor" href="#messages-enabled-on-uart2" aria-label="Permalink to &quot;Messages Enabled on UART2&quot;">​</a></h2><p>The following messages are enabled when <code>GPS_UBX_MODE</code> is set to <code>7</code>:</p><table tabindex="0"><thead><tr><th>Повідомлення</th><th>Rate</th></tr></thead><tbody><tr><td><code>NAV-PVT</code>, <code>NAV-DOP</code>, <code>NAV-STATUS</code>, <code>MON-RF</code></td><td>Every navigation epoch</td></tr><tr><td><code>NAV-HPPOSLLH</code></td><td>Every epoch, except M9</td></tr><tr><td><code>RXM-RTCM</code></td><td>Every epoch, M9 and F9P</td></tr><tr><td><code>NAV-SAT</code></td><td>Every 10th epoch</td></tr></tbody></table><p>The set runs around 300 bytes per navigation epoch (GPS update cycle), roughly triple that on the epoch carrying <code>NAV-SAT</code>.</p><p>The default <code>UART2</code> baud rate (230400) covers the 25 Hz maximum; 115200 is the practical floor at the 10 Hz default rate. Below that, the <code>NAV-SAT</code> epoch saturates the link, and a u-blox receiver drops messages on a congested port rather than throttling: the result is gaps in u-center.</p><h2 id="обмеження" tabindex="-1">Обмеження <a class="header-anchor" href="#обмеження" aria-label="Permalink to &quot;Обмеження&quot;">​</a></h2><ul><li>UBX input is enabled on <code>UART2</code>, so anything connected there can reconfigure the receiver. Use this on the bench, not in flight.</li><li>The driver writes to the receiver&#39;s RAM configuration layer on every boot. Changes made from u-center to the RAM layer are lost at the next power cycle; changes written to BBR or flash persist and will fight the driver.</li><li><code>GPS_UBX_MODE</code> 1, 2 and 5 use <code>UART2</code> for RTCM, so heading and static-base-on-UART2 setups cannot use mode 7.</li><li>The mode is skipped with a warning on M10 and F10 receivers, and on receivers older than u-blox protocol version 27.</li></ul>',16))])}const T=o(h,[["render",l]]);export{m as __pageData,T as default};
